      fail(`Unknown argument: ${key}`);
    }
  }
}

function getQuery(args) {
  if (!('query' in args)) {
    fail('Missing required argument: query');
  }
  if (typeof args.query !== 'string') {
    fail('query must be a string');
  }
  return args.query;
}

function getOffset(args) {
  if (!('offset' in args)) return DEFAULTS.offset;
  if (typeof args.offset !== 'number' || !Number.isInteger(args.offset) || args.offset < 0) {
    fail('offset must be a non-negative integer');
  }
  return args.offset;
}

function getLimit(args) {
  if (!('limit' in args)) return DEFAULTS.limit;
  if (typeof args.limit !== 'number' || !Number.isInteger(args.limit) || args.limit < LIMIT_MIN || args.limit > LIMIT_MAX) {
    fail(`limit must be an integer between ${LIMIT_MIN} and ${LIMIT_MAX}`);
  }
  return args.limit;
}

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'Search catalog items by name (case-insensitive) with pagination.',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        required: ['query'],
        properties: {
          query: {
            type: 'string',
            description: 'Substring to match against item names (case-insensitive).',
          },
          offset: {
            type: 'integer',
            minimum: 0,
