import('./server.mjs').then(async ({listTools, callTool}) => {
  const cases = [
    ['listTools', () => listTools()],
    ['happy: query+limit 2', async () => callTool('catalog_search', {query:'widget', limit:2})],
    ['happy: defaults', async () => callTool('catalog_search', {query:'widget'})],
    ['happy: case-insensitive (WIDGET)', async () => callTool('catalog_search', {query:'WIDGET', limit:1})],
    ['last page omits next_offset', async () => callTool('catalog_search', {query:'widget', offset:2, limit:5})],
    ['unknown tool', async () => callTool('nope', {})],
    ['missing query', async () => callTool('catalog_search', {})],
    ['non-string query', async () => callTool('catalog_search', {query:1})],
    ['extra arg', async () => callTool('catalog_search', {query:'x', foo:1})],
    ['limit too low', async () => callTool('catalog_search', {query:'a', limit:0})],
    ['limit too high', async () => callTool('catalog_search', {query:'a', limit:6})],
    ['non-integer limit', async () => callTool('catalog_search', {query:'a', limit:2.5})],
    ['negative offset', async () => callTool('catalog_search', {query:'a', offset:-1})],
  ];
  for (const [label, fn] of cases) {
    try { const r = await fn(); console.log('OK  ', label, '=>', JSON.stringify(r)); }
    catch (e) { console.log('ERR ', label, '=>', e.message); }
  }
});
